

-- =====================================================================
-- 1. CREACIÓN DE BASE DE DATOS
-- =====================================================================

CREATE DATABASE IF NOT EXISTS olimpiadas_bd
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE olimpiadas_bd;


-- =====================================================================
-- 2. LIMPIEZA PREVIA
-- =====================================================================

SET FOREIGN_KEY_CHECKS = 0;

DROP VIEW IF EXISTS v_tabla_posicion;
DROP VIEW IF EXISTS v_proximos_partidos;
DROP VIEW IF EXISTS v_goleadores;

DROP TABLE IF EXISTS `notificacion`;
DROP TABLE IF EXISTS `tabla_posicion`;
DROP TABLE IF EXISTS `estadistica_jugador`;
DROP TABLE IF EXISTS `sorteo_log`;
DROP TABLE IF EXISTS `resultado`;
DROP TABLE IF EXISTS `partido`;
DROP TABLE IF EXISTS `sede`;
DROP TABLE IF EXISTS `grupo_equipo`;
DROP TABLE IF EXISTS `grupo`;
DROP TABLE IF EXISTS `equipo_participante`;
DROP TABLE IF EXISTS `participante`;
DROP TABLE IF EXISTS `equipo`;
DROP TABLE IF EXISTS `evento_deporte`;
DROP TABLE IF EXISTS `evento`;
DROP TABLE IF EXISTS `usuario`;
DROP TABLE IF EXISTS `rol`;
DROP TABLE IF EXISTS `institucion`;
DROP TABLE IF EXISTS `deporte_categoria`;
DROP TABLE IF EXISTS `deporte`;
DROP TABLE IF EXISTS `categoria`;

SET FOREIGN_KEY_CHECKS = 1;


-- =====================================================================
-- 3. CATÁLOGOS BASE
-- =====================================================================

-- Clasificación de participación: VARONES, DAMAS, MIXTO, LIBRE
CREATE TABLE `categoria` (
  `id_categoria` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nombre` varchar(80) NOT NULL,
  `descripcion` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=5;

-- Catálogo de disciplinas deportivas disponibles
CREATE TABLE `deporte` (
  `id_deporte` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `tipo` enum('INDIVIDUAL','GRUPAL') NOT NULL DEFAULT 'GRUPAL',
  `max_jugadores` tinyint(3) UNSIGNED DEFAULT NULL,
  `min_jugadores` tinyint(3) UNSIGNED DEFAULT NULL,
  `estado` enum('ACTIVO','INACTIVO') NOT NULL DEFAULT 'ACTIVO',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_deporte`),
  UNIQUE KEY `nombre` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=20;

-- Tabla puente: categorías permitidas para cada deporte (N:N)
CREATE TABLE `deporte_categoria` (
  `id_deporte_categoria` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_deporte` int(10) UNSIGNED NOT NULL,
  `id_categoria` int(10) UNSIGNED NOT NULL,
  PRIMARY KEY (`id_deporte_categoria`),
  UNIQUE KEY `uq_dep_cat` (`id_deporte`,`id_categoria`),
  KEY `fk_dc_categoria` (`id_categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=25;


-- =====================================================================
-- 4. SEGURIDAD Y USUARIOS
-- =====================================================================

-- Instituciones / colegios / universidades participantes
CREATE TABLE `institucion` (
  `id_institucion` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) NOT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `email` varchar(100) DEFAULT NULL,
  `logo` longblob DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_institucion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=15;

-- Roles del sistema (permisos)
CREATE TABLE `rol` (
  `id_rol` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `nombre` varchar(50) NOT NULL,
  `descripcion` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id_rol`),
  UNIQUE KEY `nombre` (`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=6;

-- Cuentas de acceso al sistema
CREATE TABLE `usuario` (
  `id_usuario` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_institucion` int(10) UNSIGNED DEFAULT NULL,
  `id_rol` int(10) UNSIGNED NOT NULL,
  `nombres` varchar(100) NOT NULL,
  `apellidos` varchar(100) NOT NULL,
  `email` varchar(100) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `email` (`email`),
  KEY `fk_usuario_institucion` (`id_institucion`),
  KEY `fk_usuario_rol` (`id_rol`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=7;


-- =====================================================================
-- 5. EVENTOS Y COMPETENCIAS
-- =====================================================================

-- Evento deportivo general (ej. 'Olimpiadas UTP 2026')
CREATE TABLE `evento` (
  `id_evento` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_institucion` int(10) UNSIGNED NOT NULL,
  `nombre` varchar(150) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `fecha_limite_insc` date NOT NULL,
  `premio` varchar(255) DEFAULT NULL,
  `min_equipos` tinyint(3) UNSIGNED NOT NULL DEFAULT 2,
  `estado` enum('BORRADOR','ABIERTO','EN_CURSO','FINALIZADO','CANCELADO') NOT NULL DEFAULT 'BORRADOR',
  `id_usuario_creador` int(10) UNSIGNED NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_evento`),
  KEY `fk_evento_institucion` (`id_institucion`),
  KEY `fk_evento_creador` (`id_usuario_creador`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=26;

-- Competencia específica dentro de un evento (deporte + categoría)
CREATE TABLE `evento_deporte` (
  `id_evento_deporte` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_evento` int(10) UNSIGNED NOT NULL,
  `id_deporte` int(10) UNSIGNED NOT NULL,
  `id_categoria` int(10) UNSIGNED NOT NULL,
  PRIMARY KEY (`id_evento_deporte`),
  UNIQUE KEY `uq_ev_dep_cat` (`id_evento`,`id_deporte`,`id_categoria`),
  KEY `fk_ed_deporte` (`id_deporte`),
  KEY `fk_ed_categoria` (`id_categoria`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=19;


-- =====================================================================
-- 6. EQUIPOS Y PARTICIPANTES
-- =====================================================================

-- Equipos inscritos en una competencia (evento_deporte)
CREATE TABLE `equipo` (
  `id_equipo` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_evento_deporte` int(10) UNSIGNED NOT NULL,
  `id_institucion` int(10) UNSIGNED NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `color_uniforme` varchar(50) DEFAULT NULL,
  `estado_inscripcion` enum('PENDIENTE','APROBADO','RECHAZADO','RETIRADO') NOT NULL DEFAULT 'PENDIENTE',
  `motivo_rechazo` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_equipo`),
  KEY `fk_equipo_evento_dep` (`id_evento_deporte`),
  KEY `fk_equipo_institucion` (`id_institucion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=55;

-- Personas (jugadores) registradas en el sistema
CREATE TABLE `participante` (
  `id_participante` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_institucion` int(10) UNSIGNED NOT NULL,
  `nombres` varchar(100) NOT NULL,
  `apellidos` varchar(100) NOT NULL,
  `dni` varchar(20) NOT NULL,
  `email` varchar(100) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `fecha_nacimiento` date DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_participante`),
  UNIQUE KEY `dni` (`dni`),
  KEY `fk_participante_inst` (`id_institucion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=109;

-- Tabla puente: miembros de cada equipo (N:N)
CREATE TABLE `equipo_participante` (
  `id_equipo_participante` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_equipo` int(10) UNSIGNED NOT NULL,
  `id_participante` int(10) UNSIGNED NOT NULL,
  `es_capitan` tinyint(1) NOT NULL DEFAULT 0,
  `estado` enum('ACTIVO','INACTIVO','SUSPENDIDO') NOT NULL DEFAULT 'ACTIVO',
  `fecha_inscripcion` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_equipo_participante`),
  UNIQUE KEY `uq_eq_part` (`id_equipo`,`id_participante`),
  KEY `fk_ep_participante` (`id_participante`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=13;


-- =====================================================================
-- 7. SORTEO Y PROGRAMACIÓN DE PARTIDOS
-- =====================================================================

-- Grupos de fase de grupos generados por sorteo (Grupo A, B, C...)
CREATE TABLE `grupo` (
  `id_grupo` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_evento_deporte` int(10) UNSIGNED NOT NULL,
  `nombre` varchar(10) NOT NULL,
  `estado` enum('ACTIVO','CERRADO') NOT NULL DEFAULT 'ACTIVO',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_grupo`),
  UNIQUE KEY `uq_grupo` (`id_evento_deporte`,`nombre`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=18;

-- Equipos asignados a cada grupo (resultado del sorteo)
CREATE TABLE `grupo_equipo` (
  `id_grupo_equipo` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_grupo` int(10) UNSIGNED NOT NULL,
  `id_equipo` int(10) UNSIGNED NOT NULL,
  `posicion` tinyint(3) UNSIGNED DEFAULT NULL,
  PRIMARY KEY (`id_grupo_equipo`),
  UNIQUE KEY `uq_grupo_eq` (`id_grupo`,`id_equipo`),
  KEY `fk_ge_equipo` (`id_equipo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=45;

-- Lugares físicos donde se juegan los partidos
CREATE TABLE `sede` (
  `id_sede` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_institucion` int(10) UNSIGNED NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `ubicacion` varchar(255) DEFAULT NULL,
  `activo` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id_sede`),
  KEY `fk_sede_inst` (`id_institucion`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=4;

-- Partidos programados entre dos equipos
CREATE TABLE `partido` (
  `id_partido` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_evento_deporte` int(10) UNSIGNED NOT NULL,
  `id_grupo` int(10) UNSIGNED DEFAULT NULL,
  `id_equipo_local` int(10) UNSIGNED NOT NULL,
  `id_equipo_visitante` int(10) UNSIGNED NOT NULL,
  `id_sede` int(10) UNSIGNED DEFAULT NULL,
  `id_arbitro` int(10) UNSIGNED DEFAULT NULL,
  `fecha_hora` datetime NOT NULL,
  `fase` enum('GRUPO','OCTAVOS','CUARTOS','SEMIFINAL','TERCER_PUESTO','FINAL') NOT NULL DEFAULT 'GRUPO',
  `estado` enum('PROGRAMADO','EN_CURSO','FINALIZADO','POSTERGADO','CANCELADO') NOT NULL DEFAULT 'PROGRAMADO',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_partido`),
  KEY `fk_partido_ev_dep` (`id_evento_deporte`),
  KEY `fk_partido_grupo` (`id_grupo`),
  KEY `fk_partido_local` (`id_equipo_local`),
  KEY `fk_partido_visita` (`id_equipo_visitante`),
  KEY `fk_partido_sede` (`id_sede`),
  KEY `fk_partido_arbitro` (`id_arbitro`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=76;

-- Marcador final de cada partido (relación 1:1 con partido)
CREATE TABLE `resultado` (
  `id_resultado` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_partido` int(10) UNSIGNED NOT NULL,
  `goles_local` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `goles_visitante` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `ganador` enum('LOCAL','VISITANTE','EMPATE') NOT NULL,
  `penales_local` tinyint(3) UNSIGNED DEFAULT NULL,
  `penales_visitante` tinyint(3) UNSIGNED DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `publicado` tinyint(1) NOT NULL DEFAULT 0,
  `fecha_registro` datetime NOT NULL DEFAULT current_timestamp(),
  `id_usuario_registro` int(10) UNSIGNED NOT NULL,
  PRIMARY KEY (`id_resultado`),
  UNIQUE KEY `id_partido` (`id_partido`),
  KEY `fk_resultado_usuario` (`id_usuario_registro`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Historial / auditoría de los sorteos ejecutados
CREATE TABLE `sorteo_log` (
  `id_sorteo_log` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_evento_deporte` int(10) UNSIGNED NOT NULL,
  `id_usuario` int(10) UNSIGNED NOT NULL,
  `fecha_sorteo` datetime NOT NULL DEFAULT current_timestamp(),
  `resultado_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`resultado_json`)),
  `observaciones` text DEFAULT NULL,
  PRIMARY KEY (`id_sorteo_log`),
  KEY `fk_sl_ev_dep` (`id_evento_deporte`),
  KEY `fk_sl_usuario` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci AUTO_INCREMENT=8;


-- =====================================================================
-- 8. ESTADÍSTICAS Y TABLA DE POSICIONES
-- =====================================================================

-- Estadísticas individuales por jugador y partido (goles, asistencias, etc.)
CREATE TABLE `estadistica_jugador` (
  `id_estadistica` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_partido` int(10) UNSIGNED NOT NULL,
  `id_participante` int(10) UNSIGNED NOT NULL,
  `goles` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `asistencias` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `tarjetas_amarillas` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `tarjetas_rojas` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `minutos_jugados` smallint(5) UNSIGNED DEFAULT NULL,
  `observaciones` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_estadistica`),
  KEY `fk_ej_partido` (`id_partido`),
  KEY `fk_ej_participante` (`id_participante`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Posiciones acumuladas por equipo dentro de cada grupo
CREATE TABLE `tabla_posicion` (
  `id_tabla_posicion` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_grupo` int(10) UNSIGNED NOT NULL,
  `id_equipo` int(10) UNSIGNED NOT NULL,
  `partidos_jugados` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `victorias` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `empates` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `derrotas` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `goles_favor` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `goles_contra` smallint(5) UNSIGNED NOT NULL DEFAULT 0,
  `diferencia_goles` smallint(6) NOT NULL DEFAULT 0,
  `puntos` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id_tabla_posicion`),
  UNIQUE KEY `uq_pos` (`id_grupo`,`id_equipo`),
  KEY `fk_tp_equipo` (`id_equipo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- =====================================================================
-- 9. NOTIFICACIONES
-- =====================================================================

-- Notificaciones enviadas a los usuarios (sistema, email, SMS)
CREATE TABLE `notificacion` (
  `id_notificacion` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `id_usuario_destino` int(10) UNSIGNED DEFAULT NULL,
  `id_evento` int(10) UNSIGNED DEFAULT NULL,
  `tipo` enum('CONFIRMACION','ERROR','ALERTA','INFORMACION') NOT NULL,
  `asunto` varchar(150) NOT NULL,
  `mensaje` text NOT NULL,
  `canal` enum('EMAIL','SISTEMA','SMS') NOT NULL DEFAULT 'SISTEMA',
  `leido` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_notificacion`),
  KEY `fk_noti_usuario` (`id_usuario_destino`),
  KEY `fk_noti_evento` (`id_evento`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- =====================================================================
-- 10. LLAVES FORÁNEAS (FOREIGN KEY)
-- =====================================================================

ALTER TABLE `deporte_categoria`
  ADD CONSTRAINT `fk_dc_categoria` FOREIGN KEY (`id_categoria`) REFERENCES `categoria` (`id_categoria`),
  ADD CONSTRAINT `fk_dc_deporte` FOREIGN KEY (`id_deporte`) REFERENCES `deporte` (`id_deporte`);

ALTER TABLE `usuario`
  ADD CONSTRAINT `fk_usuario_institucion` FOREIGN KEY (`id_institucion`) REFERENCES `institucion` (`id_institucion`),
  ADD CONSTRAINT `fk_usuario_rol` FOREIGN KEY (`id_rol`) REFERENCES `rol` (`id_rol`);

ALTER TABLE `evento`
  ADD CONSTRAINT `fk_evento_creador` FOREIGN KEY (`id_usuario_creador`) REFERENCES `usuario` (`id_usuario`),
  ADD CONSTRAINT `fk_evento_institucion` FOREIGN KEY (`id_institucion`) REFERENCES `institucion` (`id_institucion`);

ALTER TABLE `evento_deporte`
  ADD CONSTRAINT `fk_ed_categoria` FOREIGN KEY (`id_categoria`) REFERENCES `categoria` (`id_categoria`),
  ADD CONSTRAINT `fk_ed_deporte` FOREIGN KEY (`id_deporte`) REFERENCES `deporte` (`id_deporte`),
  ADD CONSTRAINT `fk_ed_evento` FOREIGN KEY (`id_evento`) REFERENCES `evento` (`id_evento`);

ALTER TABLE `equipo`
  ADD CONSTRAINT `fk_equipo_evento_dep` FOREIGN KEY (`id_evento_deporte`) REFERENCES `evento_deporte` (`id_evento_deporte`),
  ADD CONSTRAINT `fk_equipo_institucion` FOREIGN KEY (`id_institucion`) REFERENCES `institucion` (`id_institucion`);

ALTER TABLE `participante`
  ADD CONSTRAINT `fk_participante_inst` FOREIGN KEY (`id_institucion`) REFERENCES `institucion` (`id_institucion`);

ALTER TABLE `equipo_participante`
  ADD CONSTRAINT `fk_ep_equipo` FOREIGN KEY (`id_equipo`) REFERENCES `equipo` (`id_equipo`),
  ADD CONSTRAINT `fk_ep_participante` FOREIGN KEY (`id_participante`) REFERENCES `participante` (`id_participante`);

ALTER TABLE `grupo`
  ADD CONSTRAINT `fk_grupo_ev_dep` FOREIGN KEY (`id_evento_deporte`) REFERENCES `evento_deporte` (`id_evento_deporte`);

ALTER TABLE `grupo_equipo`
  ADD CONSTRAINT `fk_ge_equipo` FOREIGN KEY (`id_equipo`) REFERENCES `equipo` (`id_equipo`),
  ADD CONSTRAINT `fk_ge_grupo` FOREIGN KEY (`id_grupo`) REFERENCES `grupo` (`id_grupo`);

ALTER TABLE `sede`
  ADD CONSTRAINT `fk_sede_inst` FOREIGN KEY (`id_institucion`) REFERENCES `institucion` (`id_institucion`);

ALTER TABLE `partido`
  ADD CONSTRAINT `fk_partido_arbitro` FOREIGN KEY (`id_arbitro`) REFERENCES `usuario` (`id_usuario`),
  ADD CONSTRAINT `fk_partido_ev_dep` FOREIGN KEY (`id_evento_deporte`) REFERENCES `evento_deporte` (`id_evento_deporte`),
  ADD CONSTRAINT `fk_partido_grupo` FOREIGN KEY (`id_grupo`) REFERENCES `grupo` (`id_grupo`),
  ADD CONSTRAINT `fk_partido_local` FOREIGN KEY (`id_equipo_local`) REFERENCES `equipo` (`id_equipo`),
  ADD CONSTRAINT `fk_partido_sede` FOREIGN KEY (`id_sede`) REFERENCES `sede` (`id_sede`),
  ADD CONSTRAINT `fk_partido_visita` FOREIGN KEY (`id_equipo_visitante`) REFERENCES `equipo` (`id_equipo`);

ALTER TABLE `resultado`
  ADD CONSTRAINT `fk_resultado_partido` FOREIGN KEY (`id_partido`) REFERENCES `partido` (`id_partido`),
  ADD CONSTRAINT `fk_resultado_usuario` FOREIGN KEY (`id_usuario_registro`) REFERENCES `usuario` (`id_usuario`);

ALTER TABLE `sorteo_log`
  ADD CONSTRAINT `fk_sl_ev_dep` FOREIGN KEY (`id_evento_deporte`) REFERENCES `evento_deporte` (`id_evento_deporte`),
  ADD CONSTRAINT `fk_sl_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuario` (`id_usuario`);

ALTER TABLE `estadistica_jugador`
  ADD CONSTRAINT `fk_ej_participante` FOREIGN KEY (`id_participante`) REFERENCES `participante` (`id_participante`),
  ADD CONSTRAINT `fk_ej_partido` FOREIGN KEY (`id_partido`) REFERENCES `partido` (`id_partido`);

ALTER TABLE `tabla_posicion`
  ADD CONSTRAINT `fk_tp_equipo` FOREIGN KEY (`id_equipo`) REFERENCES `equipo` (`id_equipo`),
  ADD CONSTRAINT `fk_tp_grupo` FOREIGN KEY (`id_grupo`) REFERENCES `grupo` (`id_grupo`);

ALTER TABLE `notificacion`
  ADD CONSTRAINT `fk_noti_evento` FOREIGN KEY (`id_evento`) REFERENCES `evento` (`id_evento`),
  ADD CONSTRAINT `fk_noti_usuario` FOREIGN KEY (`id_usuario_destino`) REFERENCES `usuario` (`id_usuario`);


-- =====================================================================
-- 11. DATOS (INSERT) DE TODAS LAS TABLAS
-- Se mantiene el mismo orden de dependencias que la creación de tablas.
-- =====================================================================

-- --- 3. CATÁLOGOS BASE ---

INSERT INTO `categoria` (`id_categoria`, `nombre`, `descripcion`) VALUES
(1, 'VARONES', NULL),
(2, 'DAMAS', NULL),
(3, 'MIXTO', NULL),
