-- =====================================================================
-- 12. VISTAS DE REPORTE
-- =====================================================================

-- Próximos partidos programados, con datos de evento/deporte/equipos/sede
DROP VIEW IF EXISTS `v_proximos_partidos`;
CREATE OR REPLACE VIEW `v_proximos_partidos` AS SELECT `pa`.`id_partido` AS `id_partido`, `e`.`nombre` AS `evento`, `d`.`nombre` AS `deporte`, `g`.`nombre` AS `grupo`, `pa`.`fase` AS `fase`, `el`.`nombre` AS `equipo_local`, `ev`.`nombre` AS `equipo_visitante`, `s`.`nombre` AS `sede`, `pa`.`fecha_hora` AS `fecha_hora`, `pa`.`estado` AS `estado` FROM (((((((`partido` `pa` join `evento_deporte` `ed` on(`ed`.`id_evento_deporte` = `pa`.`id_evento_deporte`)) join `evento` `e` on(`e`.`id_evento` = `ed`.`id_evento`)) join `deporte` `d` on(`d`.`id_deporte` = `ed`.`id_deporte`)) left join `grupo` `g` on(`g`.`id_grupo` = `pa`.`id_grupo`)) join `equipo` `el` on(`el`.`id_equipo` = `pa`.`id_equipo_local`)) join `equipo` `ev` on(`ev`.`id_equipo` = `pa`.`id_equipo_visitante`)) left join `sede` `s` on(`s`.`id_sede` = `pa`.`id_sede`)) WHERE `pa`.`estado` = 'PROGRAMADO' ORDER BY `pa`.`fecha_hora` ASC;

-- Ranking de goleadores y asistencias por jugador
DROP VIEW IF EXISTS `v_goleadores`;
CREATE OR REPLACE VIEW `v_goleadores` AS SELECT `e`.`nombre` AS `evento`, `d`.`nombre` AS `deporte`, concat(`p`.`nombres`,' ',`p`.`apellidos`) AS `jugador`, `eq`.`nombre` AS `equipo`, sum(`ej`.`goles`) AS `total_goles`, sum(`ej`.`asistencias`) AS `total_asistencias` FROM (((((((`estadistica_jugador` `ej` join `participante` `p` on(`p`.`id_participante` = `ej`.`id_participante`)) join `partido` `pa` on(`pa`.`id_partido` = `ej`.`id_partido`)) join `evento_deporte` `ed` on(`ed`.`id_evento_deporte` = `pa`.`id_evento_deporte`)) join `evento` `e` on(`e`.`id_evento` = `ed`.`id_evento`)) join `deporte` `d` on(`d`.`id_deporte` = `ed`.`id_deporte`)) join `equipo_participante` `ep` on(`ep`.`id_participante` = `ej`.`id_participante`)) join `equipo` `eq` on(`eq`.`id_equipo` = `ep`.`id_equipo`)) GROUP BY `e`.`id_evento`, `d`.`id_deporte`, `p`.`id_participante`, `eq`.`id_equipo` ORDER BY sum(`ej`.`goles`) DESC;

-- Tabla de posiciones por grupo (PJ, G, E, P, GF, GC, DG, PTS)
DROP VIEW IF EXISTS `v_tabla_posicion`;
CREATE OR REPLACE VIEW `v_tabla_posicion` AS SELECT `e`.`nombre` AS `evento`, `d`.`nombre` AS `deporte`, `c`.`nombre` AS `categoria`, `g`.`nombre` AS `grupo`, `eq`.`nombre` AS `equipo`, `tp`.`partidos_jugados` AS `PJ`, `tp`.`victorias` AS `G`, `tp`.`empates` AS `E`, `tp`.`derrotas` AS `P`, `tp`.`goles_favor` AS `GF`, `tp`.`goles_contra` AS `GC`, `tp`.`diferencia_goles` AS `DG`, `tp`.`puntos` AS `PTS` FROM ((((((`tabla_posicion` `tp` join `grupo` `g` on(`g`.`id_grupo` = `tp`.`id_grupo`)) join `evento_deporte` `ed` on(`ed`.`id_evento_deporte` = `g`.`id_evento_deporte`)) join `evento` `e` on(`e`.`id_evento` = `ed`.`id_evento`)) join `deporte` `d` on(`d`.`id_deporte` = `ed`.`id_deporte`)) join `categoria` `c` on(`c`.`id_categoria` = `ed`.`id_categoria`)) join `equipo` `eq` on(`eq`.`id_equipo` = `tp`.`id_equipo`)) ORDER BY `e`.`id_evento` ASC, `g`.`nombre` ASC, `tp`.`puntos` DESC, `tp`.`diferencia_goles` DESC;


